using System.Diagnostics;using System.Text;
namespace CSharpPracticum.Tasks.Level2;
internal class Task17_StringBuilder:ITask {public string Title=>"Задание 17: StringBuilder vs конкатенация";public string Description=>"Сравнить производительность двух способов сборки строки.";public string[] Requirements=>new[]{"Собрать строку из 10 000 чисел двумя способами.","Измерить Stopwatch и вывести времена и разницу.","Объяснить в комментарии преимущество StringBuilder."};public void Run(){Stopwatch w=Stopwatch.StartNew();string a="";for(int i=0;i<10000;i++)a+=i;w.Stop();long t1=w.ElapsedMilliseconds;w.Restart();StringBuilder b=new();for(int i=0;i<10000;i++)b.Append(i);w.Stop();Console.WriteLine($"Конкатенация: {t1} мс; StringBuilder: {w.ElapsedMilliseconds} мс; разница: {Math.Abs(t1-w.ElapsedMilliseconds)} мс");Console.WriteLine($"Результаты совпадают: {a==b.ToString()}");/* StringBuilder изменяет существующий буфер, а конкатенация создаёт новые строки. */}}
